(()=>{const q=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function loadBridge(){try{return await import('@forge/bridge');}catch(_){return null;}}function counter(module,id){return module?.counters?.find?.(x=>x.id===id)?.value??0;}function renderModule(module,sectionId,hostId){const section=q(sectionId),host=q(hostId);if(!section||!host||!module){if(section)section.hidden=true;return;}const counters=(module.counters||[]).map(c=>`<div class="companion-stat"><strong>${esc(c.value)}</strong><span>${esc(c.label)}</span></div>`).join('');const rows=(module.items||[]).map(item=>`<button type="button" class="companion-row" data-url="${esc(item.url||'')}"><span><strong>${esc(item.title)}</strong><small>${esc(item.subtitle||'')}</small></span><span class="companion-badge">${esc(item.badge||item.status||'')}</span></button>`).join('');host.innerHTML=`<div class="companion-stats">${counters}</div><div class="companion-list">${rows||'<div class="companion-empty">Nothing needs your attention right now.</div>'}</div>`;section.hidden=false;host.querySelectorAll('[data-url]').forEach(btn=>btn.onclick=()=>{const url=btn.dataset.url;if(url)window.top.location.href=url;});}
function bars(items=[]){const max=Math.max(1,...items.map(x=>Number(x.value)||0));return items.slice(0,8).map(x=>`<div class="mini-bar-row"><span>${esc(x.label)}</span><i><b style="width:${Math.max(3,Math.round((Number(x.value||0)/max)*100))}%"></b></i><strong>${esc(x.value)}</strong></div>`).join('');}
function renderReports(selfService){const section=q('reports-section'),cards=q('report-cards'),charts=q('report-charts'),report=selfService?.report;if(!section||!cards||!charts||!selfService?.reporting?.enabled||!report){if(section)section.hidden=true;return;}const avg=report.averageResolutionMs==null?'—':`${Math.max(0.1,report.averageResolutionMs/86400000).toFixed(1)} days`;const slaPct=report.sla?.measured?Math.round((report.sla.met/report.sla.measured)*100):null;cards.innerHTML=`<div class="report-card"><strong>${report.created}</strong><span>Requests created</span></div><div class="report-card"><strong>${report.resolved}</strong><span>Requests resolved</span></div><div class="report-card"><strong>${slaPct==null?'—':slaPct+'%'}</strong><span>SLA met</span></div><div class="report-card"><strong>${esc(avg)}</strong><span>Average resolution</span></div>`;charts.innerHTML=`<article class="report-panel"><h4>Requests by type</h4>${bars(report.byRequestType)}</article><article class="report-panel"><h4>Tickets by status</h4>${bars(report.byStatus)}</article><article class="report-panel"><h4>SLA performance</h4><div class="sla-summary"><strong>${report.sla?.met||0}</strong><span>Met</span><strong>${report.sla?.breached||0}</strong><span>Breached</span></div></article><article class="report-panel"><h4>Created vs resolved</h4><div class="created-resolved"><div><span>Created</span><strong>${report.created}</strong></div><div><span>Resolved</span><strong>${report.resolved}</strong></div><div><span>Open</span><strong>${report.open}</strong></div></div></article>`;section.hidden=false;}
function renderSlaBadge(selfService){if(!selfService?.sla?.enabled)return;document.querySelectorAll('.request').forEach(row=>{if(row.querySelector('.sla-pill'))return;const pill=document.createElement('span');pill.className='sla-pill';pill.textContent='SLA visible';row.appendChild(pill);});}
async function start(){const bridge=await loadBridge();if(!bridge?.invoke)return;try{const result=await Promise.race([bridge.invoke('getDashboard'),new Promise((_,reject)=>setTimeout(()=>reject(new Error('enhancements timeout')),10000))]);if(!result?.audienceAllowed)return;renderReports(result.selfService);const modules=Array.isArray(result.integrations)?result.integrations:[];renderModule(modules.find(m=>m.id==='assets'),'assets-section','assets-module');renderModule(modules.find(m=>m.id==='smart-approval'),'approvals-section','approvals-module');renderSlaBadge(result.selfService);window.dispatchEvent(new CustomEvent('portalplus:enhancements-ready',{detail:{selfService:result.selfService,integrations:modules}}));}catch(_){/* Core Portal+ must remain usable if optional enhancements fail. */}}
window.addEventListener('load',()=>setTimeout(start,50));})();